import pandas as pd
import json

def task_func(file_path, key):
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, list):
        processed_data = []
        for item in data:
            if isinstance(item, dict):
                processed_data.append({k: v for k, v in item.items() if k != key})
            else:
                processed_data.append(item)
        df = pd.DataFrame(processed_data)
    elif isinstance(data, dict):
        processed_item = {k: v for k, v in data.items() if k != key}
        df = pd.DataFrame([processed_item])
    else:
        df = pd.DataFrame(data)

    df.to_json(file_path, orient="records", indent=4, force_ascii=False)
    return df
